import{_ as p,a0 as l,w as d,s as r,I as a,x as n,a1 as i,A as t,ao as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"在 KVM 中測試 IPv6 網絡：第 2 部分 | LCTT x X-CMD","titleTemplate":false,"description":"在 KVM 中測試 IPv6 網絡：第 2 部分 | LCTT (201805) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 KVM 中測試 IPv6 網絡：第 2 部分 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 KVM 中測試 IPv6 網絡：第 2 部分 | LCTT (201805) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201805/20171109 Testing IPv6 Networking in KVM- Part 2","title":"在 KVM 中測試 IPv6 網絡：第 2 部分","tag":"201805","desc":""},"relativePath":"201805/20171109 Testing IPv6 Networking in KVM- Part 2.md","filePath":"[post].md"}'),f={name:"201805/20171109 Testing IPv6 Networking in KVM- Part 2.md"};function m(u,s,g,b,k,c){const e=l("Link");return d(),r("div",null,[s[26]||(s[26]=a("h1",{id:"在-kvm-中測試-ipv6-網絡-第-2-部分",tabindex:"-1"},[n("在 KVM 中測試 IPv6 網絡：第 2 部分 "),a("a",{class:"header-anchor",href:"#在-kvm-中測試-ipv6-網絡-第-2-部分","aria-label":"Permalink to “在 KVM 中測試 IPv6 網絡：第 2 部分”"},"​")],-1)),s[27]||(s[27]=a("p",null,[a("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/banner_4.png?itok=yZBHylwd",alt:""})],-1)),a("p",null,[s[1]||(s[1]=n("我們又見面了，在上一篇 ",-1)),i(e,{href:"https://linux.cn/article-9594-1.html"},{default:t(()=>[...s[0]||(s[0]=[n("在 KVM 中測試 IPv6 網絡：第 1 部分",-1)])]),_:1}),s[2]||(s[2]=n(" 中，我們學習了有關 IPv6 私有地址的內容。今天，我們將使用 KVM 創建一個網絡，去測試上一星期學習的 IPv6 的內容。",-1))]),a("p",null,[s[5]||(s[5]=n("如果你想重新温習如何使用 KVM，可以查看 ",-1)),i(e,{href:"https://www.linux.com/learn/intro-to-linux/2017/5/creating-virtual-machines-kvm-part-1"},{default:t(()=>[...s[3]||(s[3]=[n("在 KVM 中創建虛擬機：第 1 部分",-1)])]),_:1}),s[6]||(s[6]=n(" 和 ",-1)),i(e,{href:"https://www.linux.com/learn/intro-to-linux/2017/5/creating-virtual-machines-kvm-part-2-networking"},{default:t(()=>[...s[4]||(s[4]=[n("在 KVM 中創建虛擬機：第 2 部分— 網絡",-1)])]),_:1}),s[7]||(s[7]=n("。",-1))]),s[28]||(s[28]=a("h3",{id:"在-kvm-中創建網絡",tabindex:"-1"},[n("在 KVM 中創建網絡 "),a("a",{class:"header-anchor",href:"#在-kvm-中創建網絡","aria-label":"Permalink to “在 KVM 中創建網絡”"},"​")],-1)),s[29]||(s[29]=a("p",null,"在 KVM 中你至少需要兩個虛擬機。當然了，如果你願意，也可以創建更多的虛擬機。在我的系統中有 Fedora、Ubuntu、以及 openSUSE。去創建一個新的 IPv6 網絡，在主虛擬機管理窗口中打開 “Edit > Connection Details > Virtual Networks”。點擊左下角的綠色十字按鈕去創建一個新的網絡（圖 1）。",-1)),s[30]||(s[30]=a("p",null,[a("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/kvm-fig-1_0.png?itok=ruqjPXxd",alt:""})],-1)),s[31]||(s[31]=a("p",null,[a("em",null,"圖 1：創建一個網絡")],-1)),s[32]||(s[32]=a("p",null,"給新網絡輸入一個名字，然後，點擊 “Forward” 按鈕。如果你願意，也可以不創建 IPv4 網絡。當你創建一個新的 IPv4 網絡時，虛擬機管理器將不讓你創建重複網絡，或者是使用了一個無效地址。在我的宿主機 Ubuntu 系統上，有效的地址是以綠色高亮顯示的，而無效地址是使用高亮的玫瑰紅色調。在我的 openSUSE 機器上沒有高亮顏色。啓用或不啓用 DHCP，以及創建或不創建一個靜態路由，然後進入下一個窗口。",-1)),a("p",null,[s[9]||(s[9]=n("選中 “Enable IPv6 network address space definition”，然後輸入你的私有地址範圍。你可以使用任何你希望的 IPv6 地址類，但是要注意，不能將你的實驗網絡泄漏到公網上去。我們將使用非常好用的 IPv6 唯一本地地址（ULA），並且使用在 ",-1)),i(e,{href:"http://simpledns.com/private-ipv6.aspx"},{default:t(()=>[...s[8]||(s[8]=[n("Simple DNS Plus",-1)])]),_:1}),s[10]||(s[10]=n(" 上的在線地址生成器，去創建我們的網絡地址。拷貝 “Combined/CID” 地址到網絡框中（圖 2）。",-1))]),s[33]||(s[33]=o(`<p><img src="https://www.linux.com/sites/lcom/files/styles/floated_images/public/kvm-fig-2.png?itok=gncdPGj-" alt="network address" title="network address"></p><p><em>圖 2：拷貝 &quot;Combined/CID&quot; 地址到網絡框中</em></p><p>虛擬機認為我的地址是無效的，因為，它顯示了高亮的玫瑰紅色。它做的對嗎？我們使用 <code>ipv6calc</code> 去驗證一下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ipv6calc -qi fd7d:844d:3e17:f3ae::/64</span></span>
<span class="line"><span>Address type: unicast, unique-local-unicast, iid, iid-local</span></span>
<span class="line"><span>Registry for address: reserved(RFC4193#3.1)</span></span>
<span class="line"><span>Address type has SLA: f3ae</span></span>
<span class="line"><span>Interface identifier: 0000:0000:0000:0000</span></span>
<span class="line"><span>Interface identifier is probably manual set</span></span></code></pre></div><p><code>ipv6calc</code> 認為沒有問題。如果感興趣，你可以改變其中一個數字為無效的東西，比如字母 <code>g</code>，然後再試一次。（問 “如果…？”，試驗和錯誤是最好的學習方法）。</p><p>我們繼續進行，啓用 DHCPv6（圖 3）。你可以接受缺省值，或者輸入一個你自己的設置值。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/floated_images/public/kvm-fig-3.png?itok=F-oAAtN9" alt=""></p><p><em>圖 3： 啓用 DHCPv6</em></p><p>我們將跳過缺省路由定義這一步，繼續進入下一屏，在那裏我們將啓用 “Isolated Virtual Network” 和 “Enable IPv6 internal routing/networking”。</p><h3 id="虛擬機網絡選擇" tabindex="-1">虛擬機網絡選擇 <a class="header-anchor" href="#虛擬機網絡選擇" aria-label="Permalink to “虛擬機網絡選擇”">​</a></h3><p>現在，你可以配置你的虛擬機去使用新的網絡。打開你的虛擬機，然後點擊頂部左側的 “i” 按鈕去打開 “Show virtual hardware details” 屏幕。在 “Add Hardware” 列點擊 “NIC” 按鈕去打開網絡選擇器，然後選擇你喜歡的新的 IPv6 網絡。點擊 “Apply”，然後重新啓動。（或者使用你喜歡的方法去重新啓動網絡，或者更新你的 DHCP 租期。）</p><h3 id="測試" tabindex="-1">測試 <a class="header-anchor" href="#測試" aria-label="Permalink to “測試”">​</a></h3><p><code>ifconfig</code> 告訴我們它做了什麼？</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ifconfig</span></span>
<span class="line"><span>ens3: flags=4163 UP,BROADCAST,RUNNING,MULTICAST  mtu 1500</span></span>
<span class="line"><span> inet 192.168.30.207  netmask 255.255.255.0  </span></span>
<span class="line"><span>   broadcast 192.168.30.255</span></span>
<span class="line"><span> inet6 fd7d:844d:3e17:f3ae::6314  </span></span>
<span class="line"><span>   prefixlen 128  scopeid 0x0</span></span>
<span class="line"><span> inet6 fe80::4821:5ecb:e4b4:d5fc  </span></span>
<span class="line"><span>   prefixlen 64  scopeid 0x20</span></span></code></pre></div><p>這是我們新的 ULA，<code>fd7d:844d:3e17:f3ae::6314</code>，它是自動生成的本地鏈路地址。如果你有興趣，可以 ping 一下，ping 網絡上的其它虛擬機：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vm1 ~$ ping6 -c2 fd7d:844d:3e17:f3ae::2c9f</span></span>
<span class="line"><span>PING fd7d:844d:3e17:f3ae::2c9f(fd7d:844d:3e17:f3ae::2c9f) 56 data bytes</span></span>
<span class="line"><span>64 bytes from fd7d:844d:3e17:f3ae::2c9f: icmp_seq=1 ttl=64 time=0.635 ms</span></span>
<span class="line"><span>64 bytes from fd7d:844d:3e17:f3ae::2c9f: icmp_seq=2 ttl=64 time=0.365 ms</span></span>
<span class="line"><span></span></span>
<span class="line"><span>vm2 ~$ ping6 -c2 fd7d:844d:3e17:f3ae:a:b:c:6314</span></span>
<span class="line"><span>PING fd7d:844d:3e17:f3ae:a:b:c:6314(fd7d:844d:3e17:f3ae:a:b:c:6314) 56 data bytes</span></span>
<span class="line"><span>64 bytes from fd7d:844d:3e17:f3ae:a:b:c:6314: icmp_seq=1 ttl=64 time=0.744 ms</span></span>
<span class="line"><span>64 bytes from fd7d:844d:3e17:f3ae:a:b:c:6314: icmp_seq=2 ttl=64 time=0.364 ms</span></span></code></pre></div><p>當你努力去理解子網時，這是一個可以讓你嘗試不同地址是否可以正常工作的快速易用的方法。你可以給單個接口分配多個 IP 地址，然後 ping 它們去看一下會發生什麼。在一個 ULA 中，接口，或者主機是 IP 地址的最後四部分，因此，你可以在那裏做任何事情，只要它們在同一個子網中即可，在那個例子中是 <code>f3ae</code>。在我的其中一個虛擬機上，我只改變了這個示例的接口 ID，以展示使用這四個部分，你可以做任何你想做的事情：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vm1 ~$ sudo /sbin/ip -6 addr add fd7d:844d:3e17:f3ae:a:b:c:6314 dev ens3</span></span>
<span class="line"><span></span></span>
<span class="line"><span>vm2 ~$ ping6 -c2 fd7d:844d:3e17:f3ae:a:b:c:6314</span></span>
<span class="line"><span>PING fd7d:844d:3e17:f3ae:a:b:c:6314(fd7d:844d:3e17:f3ae:a:b:c:6314) 56 data bytes</span></span>
<span class="line"><span>64 bytes from fd7d:844d:3e17:f3ae:a:b:c:6314: icmp_seq=1 ttl=64 time=0.744 ms</span></span>
<span class="line"><span>64 bytes from fd7d:844d:3e17:f3ae:a:b:c:6314: icmp_seq=2 ttl=64 time=0.364 ms</span></span></code></pre></div><p>現在，嘗試使用不同的子網，在下面的示例中使用了 <code>f4ae</code> 代替 <code>f3ae</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ping6 -c2 fd7d:844d:3e17:f4ae:a:b:c:6314</span></span>
<span class="line"><span>PING fd7d:844d:3e17:f4ae:a:b:c:6314(fd7d:844d:3e17:f4ae:a:b:c:6314) 56 data bytes</span></span>
<span class="line"><span>From fd7d:844d:3e17:f3ae::1 icmp_seq=1 Destination unreachable: No route</span></span>
<span class="line"><span>From fd7d:844d:3e17:f3ae::1 icmp_seq=2 Destination unreachable: No route</span></span></code></pre></div><p>這也是練習路由的好機會，以後，我們將專門做一期，如何在不使用 DHCP 情況下實現自動尋址。</p><hr>`,22)),a("p",null,[s[12]||(s[12]=n("via: ",-1)),i(e,{href:"https://www.linux.com/learn/intro-to-linux/2017/11/testing-ipv6-networking-kvm-part-2"},{default:t(()=>[...s[11]||(s[11]=[n("https://www.linux.com/learn/intro-to-linux/2017/11/testing-ipv6-networking-kvm-part-2",-1)])]),_:1})]),a("p",null,[s[17]||(s[17]=n("作者：",-1)),i(e,{href:"https://www.linux.com/users/cschroder"},{default:t(()=>[...s[13]||(s[13]=[n("CARLA SCHRODER",-1)])]),_:1}),s[18]||(s[18]=n(" 選題：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[14]||(s[14]=[n("lujun9972",-1)])]),_:1}),s[19]||(s[19]=n(" 譯者：",-1)),i(e,{href:"https://github.com/qhwdw"},{default:t(()=>[...s[15]||(s[15]=[n("qhwdw",-1)])]),_:1}),s[20]||(s[20]=n(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[16]||(s[16]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[23]||(s[23]=n("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[21]||(s[21]=[n("LCTT",-1)])]),_:1}),s[24]||(s[24]=n(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:t(()=>[...s[22]||(s[22]=[n("Linux中國",-1)])]),_:1}),s[25]||(s[25]=n(" 榮譽推出",-1))])])}const P=p(f,[["render",m]]);export{w as __pageData,P as default};
